What does this C code print?

int a = 11, b = 5;
printf("%d %d", a / b, a % b);

What does this C code print?

int x = 7;
int y = x++ * 2 + 1;
printf("%d %d", y, x);

What does this C code print?

int a = 35, b = 3;
printf("%d %d", a / b, a % b);

What does this C code print?

int a = 1, b = 11;
int m = (a > b) ? a : b;
printf("%d", m * 2);

